CREATE TABLE IF NOT EXISTS tria_meta (name VARCHAR(64) PRIMARY KEY,value TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS tria_users (id CHAR(24) PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(200) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role VARCHAR(16) NOT NULL,active INTEGER NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS tria_sessions (token CHAR(64) PRIMARY KEY,user_id CHAR(24) NOT NULL,expires BIGINT NOT NULL,csrf CHAR(64) NOT NULL,FOREIGN KEY(user_id) REFERENCES tria_users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS tria_invites (token CHAR(64) PRIMARY KEY,email VARCHAR(200) NOT NULL,role VARCHAR(16) NOT NULL,expires BIGINT NOT NULL,used INTEGER NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS tria_projects (id CHAR(24) PRIMARY KEY,name VARCHAR(200) NOT NULL,location VARCHAR(200) NOT NULL,description TEXT NOT NULL,created BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS tria_members (project_id CHAR(24) NOT NULL,user_id CHAR(24) NOT NULL,PRIMARY KEY(project_id,user_id),FOREIGN KEY(project_id) REFERENCES tria_projects(id),FOREIGN KEY(user_id) REFERENCES tria_users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS tria_tasks (id CHAR(24) PRIMARY KEY,title VARCHAR(200) NOT NULL,project_id CHAR(24) NOT NULL,assignee CHAR(24) NOT NULL,due CHAR(10) NOT NULL,status VARCHAR(40) NOT NULL,priority VARCHAR(16) NOT NULL,category VARCHAR(40) NOT NULL,description TEXT NOT NULL,created BIGINT NOT NULL,FOREIGN KEY(project_id) REFERENCES tria_projects(id),FOREIGN KEY(assignee) REFERENCES tria_users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS tria_documents (id CHAR(24) PRIMARY KEY,name VARCHAR(200) NOT NULL,project_id CHAR(24) NOT NULL,owner CHAR(24) NOT NULL,stored CHAR(24) NOT NULL,size INTEGER NOT NULL,created BIGINT NOT NULL,FOREIGN KEY(project_id) REFERENCES tria_projects(id),FOREIGN KEY(owner) REFERENCES tria_users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS tria_attempts (bucket CHAR(64) PRIMARY KEY,count INTEGER NOT NULL,started BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS tria_audit (id INTEGER PRIMARY KEY AUTO_INCREMENT,user_id CHAR(24),action VARCHAR(200) NOT NULL,created BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS tria_google (user_id CHAR(24) PRIMARY KEY,email VARCHAR(200) NOT NULL,refresh_token TEXT NOT NULL,access_token TEXT NOT NULL,expires BIGINT NOT NULL,scopes TEXT NOT NULL,created BIGINT NOT NULL,FOREIGN KEY(user_id) REFERENCES tria_users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS tria_oauth_states (state CHAR(64) PRIMARY KEY,user_id CHAR(24) NOT NULL,verifier VARCHAR(128) NOT NULL,expires BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
